import datetime

def parse_date(s: str) -> datetime.datetime:
    if not s or not s.strip():
        raise ValueError("日期字符串不能为空")
    try:
        return datetime.datetime.strptime(s.strip(), "%Y-%m-%d")
    except ValueError:
        raise ValueError(f"无法解析日期: {s!r}（期望格式 YYYY-MM-DD）") from None

